def _count_skill_markdown_files(root: Path, limit: int = 2048) -> int:
    if not root.exists() or not root.is_dir():
        return 0
    total = 0
    try:
        for _ in root.rglob("SKILL.md"):
            total += 1
            if total >= limit:
                break
    except Exception:
        return 0
    return total

